import{_ as e,o as t,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const g=JSON.parse('{"title":"Quantities / BoM Matrix","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quantities/index.md","filePath":"guide/quantities/index.md","lastUpdated":1785948798000}'),s={name:"guide/quantities/index.md"},n=o('<h1 id="quantities-bom-matrix" tabindex="-1">Quantities / BoM Matrix <a class="header-anchor" href="#quantities-bom-matrix" aria-label="Permalink to &quot;Quantities / BoM Matrix&quot;">​</a></h1><p>The Quantities view lets you plan how many of each design to produce across project phases and batches. It uses a matrix layout where you define quantities before generating the actual constructibles.</p><nav class="table-of-contents"><ul><li><a href="#matrix-layout">Matrix Layout</a></li><li><a href="#view-modes">View Modes</a><ul><li><a href="#phase-view">Phase View</a></li><li><a href="#batch-view">Batch View</a></li></ul></li><li><a href="#managing-quantities">Managing Quantities</a><ul><li><a href="#keyboard">Keyboard</a></li><li><a href="#reading-the-matrix">Reading the matrix</a></li><li><a href="#where-the-target-comes-from">Where the target comes from</a></li><li><a href="#balancing">Balancing</a></li></ul></li><li><a href="#phase-templates-and-automation">Phase templates and automation</a><ul><li><a href="#phase-templates">Phase templates</a></li><li><a href="#batch-prefixes">Batch prefixes</a></li><li><a href="#add-panels-for-module-counts">Add panels for module counts</a></li><li><a href="#auto-allocate-by-prefix">Auto-allocate by prefix</a></li></ul></li><li><a href="#generating-constructibles">Generating Constructibles</a></li><li><a href="#area-metrics">Area Metrics</a></li></ul></nav><h2 id="matrix-layout" tabindex="-1">Matrix Layout <a class="header-anchor" href="#matrix-layout" aria-label="Permalink to &quot;Matrix Layout&quot;">​</a></h2><p>The matrix is organized as:</p><ul><li><strong>Rows</strong> — Design names (assemblies and modules). Only the latest revision of each design is shown.</li><li><strong>Columns</strong> — Project phases (or batches, depending on the view).</li><li><strong>Cells</strong> — The quantity count for each design × phase combination.</li><li><strong>Totals</strong> — Row totals (all phases for a design) and column totals (all designs in a phase).</li></ul><h2 id="view-modes" tabindex="-1">View Modes <a class="header-anchor" href="#view-modes" aria-label="Permalink to &quot;View Modes&quot;">​</a></h2><p>Two buttons in the toolbar switch the axis: <strong>Phases</strong> shows the project phases, <strong>Batches</strong> shows the batches of one phase, picked in the selector beside them. The choice is kept in the address bar, so a reload or Back keeps you where you were, and a phase view can be bookmarked or shared.</p><h3 id="phase-view" tabindex="-1">Phase View <a class="header-anchor" href="#phase-view" aria-label="Permalink to &quot;Phase View&quot;">​</a></h3><p>Shows a high-level summary with one column per project phase. Each cell shows the total quantity of a design across all batches in that phase.</p><h3 id="batch-view" tabindex="-1">Batch View <a class="header-anchor" href="#batch-view" aria-label="Permalink to &quot;Batch View&quot;">​</a></h3><p>Select a specific phase to drill down into its batches. Each column represents a batch, showing the detailed quantity breakdown.</p><h2 id="managing-quantities" tabindex="-1">Managing Quantities <a class="header-anchor" href="#managing-quantities" aria-label="Permalink to &quot;Managing Quantities&quot;">​</a></h2><ul><li><strong>Edit cells</strong> — The <strong>−</strong> / <strong>+</strong> buttons appear on the cell you point at, and on the cell you select. Click the number, or just start typing, to enter one. Only whole numbers of zero or more are accepted.</li><li><strong>Add phase</strong> — Create a new project phase. You can optionally pick a phase template (see below) to pre-fill its batches.</li><li><strong>Add batch</strong> — Create a new batch within a phase.</li><li><strong>Delete phase/batch</strong> — Remove from the project.</li><li><strong>Load from project</strong> — Restore previously saved quantities.</li><li><strong>Reset</strong> — Recalculate the matrix from the units that already exist. This also deletes the quantities saved on the project, so it asks for confirmation first.</li></ul><p>Quantities are <strong>saved automatically</strong> a couple of seconds after you stop editing. The toolbar shows <em>Unsaved</em>, <em>Saving…</em> or <em>Saved</em>, with a Save button while there is anything pending, and it also saves when you leave the view.</p><h3 id="keyboard" tabindex="-1">Keyboard <a class="header-anchor" href="#keyboard" aria-label="Permalink to &quot;Keyboard&quot;">​</a></h3><table><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td>Arrow keys</td><td>move between cells</td></tr><tr><td><kbd>Tab</kbd> / <kbd>Shift</kbd>+<kbd>Tab</kbd></td><td>next / previous column</td></tr><tr><td><kbd>Enter</kbd> / <kbd>Shift</kbd>+<kbd>Enter</kbd></td><td>next / previous row</td></tr><tr><td>type a digit, or <kbd>F2</kbd></td><td>overwrite the value</td></tr><tr><td><kbd>+</kbd> / <kbd>−</kbd></td><td>step the value by one</td></tr><tr><td><kbd>Delete</kbd></td><td>set to zero</td></tr><tr><td><kbd>Esc</kbd></td><td>cancel editing, or clear the selection</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>D</kbd></td><td>copy the selected value down the column</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>V</kbd></td><td>paste a column of numbers copied from Excel</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Z</kbd> / <kbd>Ctrl</kbd>+<kbd>Y</kbd></td><td>undo / redo</td></tr></tbody></table><p>A fill-down, a paste, <em>Set multiple numbers</em> or <em>Auto-allocate by prefix</em> all undo in a single step. The <strong>?</strong> button in the toolbar lists all of this.</p><h3 id="reading-the-matrix" tabindex="-1">Reading the matrix <a class="header-anchor" href="#reading-the-matrix" aria-label="Permalink to &quot;Reading the matrix&quot;">​</a></h3><p>The second column shows <strong>assigned / target</strong> for each design, frozen next to the design name. It turns green when the two match and amber (or red, in the batch view) when they do not — that is the number to watch while filling the matrix.</p><p>Above the matrix, a status bar totals the project: target, assigned, area, and how many designs do not add up. Hover the <strong>target</strong> figure to see which IFC file each part of it came from.</p><h3 id="where-the-target-comes-from" tabindex="-1">Where the target comes from <a class="header-anchor" href="#where-the-target-comes-from" aria-label="Permalink to &quot;Where the target comes from&quot;">​</a></h3><p>The target is the number of units the IFC splitter found for each design. It is worked out from the splitter&#39;s own counts, so it updates by itself every time you split a file.</p><p>Three actions in the <strong>Bulk</strong> menu, under <em>Project totals</em>:</p><ul><li><strong>Clear the project totals</strong> — empties the targets. The splitter counts themselves are kept, so this is reversible.</li><li><strong>Recover totals</strong> — rebuilds the targets from every piece of splitter information available. It shows each design, where its number comes from, and what would change, before writing anything. The matrix is not touched.</li><li><strong>Set totals into the matrix</strong> — writes each design&#39;s project total into the phase columns.</li></ul><p>Under <em>Project matrix</em> are the actions that change your plan rather than the targets: <strong>Load numbers from project splitter</strong> and <strong>Recalculate from existing units</strong>.</p><p>If <strong>Recover totals</strong> finds nothing, this project has no splitter counts stored — split the IFC again to rebuild them.</p><h4 id="projects-without-targets" tabindex="-1">Projects without targets <a class="header-anchor" href="#projects-without-targets" aria-label="Permalink to &quot;Projects without targets&quot;">​</a></h4><p>A project you never split has no targets, and neither does a design you added by hand. Those rows show only the number you assigned: no target, no colour, no balance button, and they are not counted as not adding up. The status bar drops the target figure too. Nothing to compare against, nothing claimed.</p><p>The same applies per design, so a project where only some designs came from a split judges those and leaves the rest alone.</p><h3 id="balancing" tabindex="-1">Balancing <a class="header-anchor" href="#balancing" aria-label="Permalink to &quot;Balancing&quot;">​</a></h3><ul><li><strong>Balance a row</strong> — an unbalanced row has a button next to its assigned/target figure. It spreads the difference over the columns that already carry a number, keeping their proportions. If the row has nothing allocated yet, it all goes on the first column.</li><li><strong>Balance all</strong> — in the status bar. It shows which designs it will change, and by how much, before you commit.</li></ul><p>When a phase has many batches the matrix scrolls sideways. The design name and the target/assigned column stay frozen on the left, the header row stays on top, and the grand total stays pinned at the bottom.</p><h2 id="phase-templates-and-automation" tabindex="-1">Phase templates and automation <a class="header-anchor" href="#phase-templates-and-automation" aria-label="Permalink to &quot;Phase templates and automation&quot;">​</a></h2><p>These tools speed up setting up a phase and filling its batches. The buttons appear in the matrix toolbar when a phase (batch view) is selected.</p><h3 id="phase-templates" tabindex="-1">Phase templates <a class="header-anchor" href="#phase-templates" aria-label="Permalink to &quot;Phase templates&quot;">​</a></h3><p>A phase template is a reusable set of batches, defined once per company. Each batch in the template has a name and an optional list of <strong>name prefixes</strong> and a production line.</p><p>Templates are managed in <strong>Projects Settings → Phase templates</strong>, in an expandable section at the bottom of the page, and are available to all the projects of the company. When you create a phase, choosing a template automatically creates its batches in that phase, including their prefixes.</p><p>A phase created from a template shows a ✨ icon next to its name. Open the phase menu and choose <strong>Set phase template</strong> to see which template is applied or to apply a different one — its batches are created or updated to match.</p><h3 id="batch-prefixes" tabindex="-1">Batch prefixes <a class="header-anchor" href="#batch-prefixes" aria-label="Permalink to &quot;Batch prefixes&quot;">​</a></h3><p>Each batch can carry the name prefixes used for auto-numbering. A batch with prefixes shows a split icon next to its name. Open the batch menu and choose <strong>Prefixes</strong> to view or edit them. Templates fill these in automatically, but you can adjust them per batch at any time.</p><h3 id="add-panels-for-module-counts" tabindex="-1">Add panels for module counts <a class="header-anchor" href="#add-panels-for-module-counts" aria-label="Permalink to &quot;Add panels for module counts&quot;">​</a></h3><p>In the <strong>phase view</strong>, set how many of each module you want in a phase, then click <strong>Add panels for module counts</strong>. The panels each module contains are taken from the module&#39;s own parsed contents and set on the same phase, multiplied by the module count. This works whether you used the project splitter or only the module splitter.</p><p>A dialog asks whether to set the numbers in batches too:</p><ul><li><strong>Also batches</strong> — set the phase totals and also distribute them into the phase&#39;s batches by prefix (so you can generate right away).</li><li><strong>Only phases</strong> — set just the phase totals and leave the batches untouched.</li><li><strong>Close</strong> — do nothing.</li></ul><p>The panel totals are recalculated from the module counts each time, so clicking the button again does not double the counts.</p><p>Hover the tree icon next to a module&#39;s name to see its decomposition — the panel (assembly) design names and how many of each the module contains.</p><h3 id="auto-allocate-by-prefix" tabindex="-1">Auto-allocate by prefix <a class="header-anchor" href="#auto-allocate-by-prefix" aria-label="Permalink to &quot;Auto-allocate by prefix&quot;">​</a></h3><p>In the <strong>batch view</strong> (with a phase selected), click <strong>Auto-allocate by prefix</strong> to send each design&#39;s phase number into the batch whose prefix matches the design name. When a name matches several prefixes, the longest (most specific) prefix wins. Designs that match no batch are reported and left unassigned.</p><p>Together these give a simple flow: place module numbers on a phase → add the panels for those modules → switch to the phase&#39;s batches and auto-allocate by prefix → generate.</p><h2 id="generating-constructibles" tabindex="-1">Generating Constructibles <a class="header-anchor" href="#generating-constructibles" aria-label="Permalink to &quot;Generating Constructibles&quot;">​</a></h2><p>Once your quantities are defined, click <strong>Generate Constructibles</strong> to create the actual assembly and module instances based on the matrix counts.</p><p>The dialog shows how many units will be created and how many deleted before you commit.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>For every design, the batch quantities of a phase must add up to that phase&#39;s quantity. If they do not, the dialog lists exactly which designs and phases are off and by how much, and generation is blocked until you fix them.</p></div><p>Your saved quantities are only cleared once the units have actually been created. If generation fails, they are kept and you can retry.</p><h2 id="area-metrics" tabindex="-1">Area Metrics <a class="header-anchor" href="#area-metrics" aria-label="Permalink to &quot;Area Metrics&quot;">​</a></h2><p>Toggle the area display to see total square meters alongside quantity counts. This helps estimate material requirements and production workload.</p>',57),i=[n];function r(h,l,d,c,u,p){return t(),a("div",null,i)}const b=e(s,[["render",r]]);export{g as __pageData,b as default};
